using System.Diagnostics;
using System.Text.Json;
using LocalAI.Core;

// Deliberate child-process fixture for TFVC failure handling; never a real server.
if(args.Length>1&&args[0]=="vc")
{
    if(args[1] is "status" or "add"){Console.WriteLine("Synthetic TFVC pending add");return;}
    Console.WriteLine("Synthetic TFVC failure: nothing succeeded");Environment.ExitCode=100;return;
}

// No server, authentication or user repositories are touched by the default suite.
var output=Path.GetFullPath(args[0]);Directory.CreateDirectory(Path.GetDirectoryName(output)!);
var root=Path.Combine(Path.GetDirectoryName(output)!,"source-fixture-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
var git=SourceControl.FindTool(SourceProvider.Git)??throw new IOException("Git is required for isolated source-control tests.");
var rows=new Dictionary<string,object>();
async Task Test(string name,Func<Task> action){try{await action();rows.Add(name,true);}catch(Exception e){rows.Add(name,false);Console.Error.WriteLine(name+": "+e);}}
void Assert(bool value){if(!value)throw new IOException("Assertion failed");}
async Task Reject(Func<Task> action){try{await action();}catch(Exception e)when(e is IOException or ArgumentException){return;}throw new IOException("Expected refusal");}
async Task<string> Command(string exe,string working,params string[] parameters)
{var info=new ProcessStartInfo(exe){WorkingDirectory=working,UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};foreach(var p in parameters)info.ArgumentList.Add(p);using var process=Process.Start(info)!;var stdout=process.StandardOutput.ReadToEndAsync();var stderr=process.StandardError.ReadToEndAsync();await process.WaitForExitAsync();var text=await stdout+await stderr;if(process.ExitCode!=0)throw new IOException(text);return text;}
await Command(git,root,"init","-b","main");await Command(git,root,"config","user.name","Infinity QA");await Command(git,root,"config","user.email","infinity-qa@example.invalid");await Command(git,root,"config","commit.gpgSign","false");
var file=Path.Combine(root,"Example.txt");File.WriteAllText(file,"original\n");await Command(git,root,"add","Example.txt");await Command(git,root,"commit","-m","Synthetic initial fixture");
var service=new SourceControl([root]);SourceRequest Request(string op,string? path=null)=>new(SourceProvider.Git,root,op,path,"Reviewed QA change");
await Test("git detects installed client",()=>{Assert(Path.IsPathFullyQualified(git));return Task.CompletedTask;});
await Test("managed git lookup does not create absent cache",()=>{var cache=Path.Combine(root,"absent-managed-cache");Assert(SourceControl.FindManagedGit(cache)==null&&!Directory.Exists(cache));return Task.CompletedTask;});
await Test("unreceipted managed git is not trusted",()=>{var cache=Path.Combine(root,"unverified-managed-cache");var package=DependencyCatalog.Load().Packages.Single(p=>p.Id=="git-runtime");using var installer=new DependencyInstaller(cache);var fake=Path.Combine(installer.PackagePath(package),"cmd","git.exe");Directory.CreateDirectory(Path.GetDirectoryName(fake)!);File.WriteAllText(fake,"NOT AN EXECUTABLE");Assert(SourceControl.FindManagedGit(cache)==null&&File.ReadAllText(fake)=="NOT AN EXECUTABLE");return Task.CompletedTask;});
await Test("git reads real status",async()=>Assert((await service.Read(Request("status"))).ExitCode==0));
File.WriteAllText(file,"reviewed\n");
await Test("git displays real working diff",async()=>{var result=await service.Read(Request("diff"));Assert(result.ExitCode==0&&result.Output.Contains("+reviewed"));});
await Test("git reads history and branches",async()=>Assert((await service.Read(Request("history"))).Output.Contains("Synthetic initial")&&(await service.Read(Request("branches"))).Output.Contains("main")));
await Test("repository mutations cannot use read route",()=>Reject(async()=>{await service.Read(Request("stage",file));}));
await Test("git preview leaves index unchanged",async()=>{var plan=await service.Preview(Request("stage",file));Assert(plan.Review.Contains("reviewed")&&string.IsNullOrWhiteSpace(await Command(git,root,"diff","--cached")));});
await Test("git requires confirmation and trust",async()=>{var plan=await service.Preview(Request("stage",file));await Reject(async()=>{await service.Apply(plan,false,true);});await Reject(async()=>{await service.Apply(plan,true,false);});});
await Test("git refuses stale reviewed file",async()=>{var plan=await service.Preview(Request("stage",file));File.WriteAllText(file,"outside change\n");await Reject(async()=>{await service.Apply(plan,true,true);});File.WriteAllText(file,"reviewed\n");});
await Test("git stages reviewed selected file",async()=>{var result=await service.Apply(await service.Preview(Request("stage",file)),true,true);Assert(result.ExitCode==0&&(await Command(git,root,"diff","--cached")).Contains("+reviewed"));});
await Test("git unstages without changing file",async()=>{var result=await service.Apply(await service.Preview(Request("unstage",file)),true,true);Assert(result.ExitCode==0&&File.ReadAllText(file)=="reviewed\n"&&string.IsNullOrWhiteSpace(await Command(git,root,"diff","--cached")));});
await Test("git selected commit preserves unrelated staged file",async()=>{File.WriteAllText(Path.Combine(root,"Other.txt"),"not authorized\n");await Command(git,root,"add","Other.txt");var result=await service.Apply(await service.Preview(Request("commit",file)),true,true);var names=await Command(git,root,"show","--format=","--name-only","HEAD");Assert(result.ExitCode==0&&names.Trim()=="Example.txt"&&(await Command(git,root,"diff","--cached","--name-only")).Contains("Other.txt"));});
await Test("git disables repository hooks",async()=>{var hook=Path.Combine(root,".git","hooks","pre-commit");File.WriteAllText(hook,"#!/bin/sh\nexit 99\n");File.WriteAllText(file,"hook-safe\n");var result=await service.Apply(await service.Preview(Request("commit",file)),true,true);Assert(result.ExitCode==0);});
await Test("git rejects force and shell commands",async()=>{await Reject(async()=>{await service.Preview(Request("reset",file));});await Reject(async()=>{await service.Preview(Request("shell",file));});});
await Test("source control rejects disconnected roots and traversal",async()=>{await Reject(async()=>{await service.Read(Request("status") with{Folder=Path.GetDirectoryName(root)!});});await Reject(async()=>{await service.Preview(Request("stage","../outside.txt"));});});
await Test("source control protects configuration and metadata",async()=>{foreach(var path in new[]{"appsettings.json",".env","private.key",".svn/wc.db","$tf/state",".tf/state"})await Reject(async()=>{await service.Preview(Request("stage",Path.Combine(root,path)));});});
await Test("source control requires selected file and commit message",async()=>{await Reject(async()=>{await service.Preview(Request("stage"));});await Reject(async()=>{await service.Preview(Request("commit",file) with{Message=""});});});
await Test("source control missing client fails before process launch",async()=>{var missing=new SourceControl([root],_=>null);await Reject(async()=>{await missing.Read(Request("status"));});});
await Test("source control rejects repository installed executables",async()=>{var exe=Path.Combine(root,"fake.exe");File.WriteAllText(exe,"not executable");await Reject(async()=>{await new SourceControl([root],_=>exe).Read(Request("status"));});});
await Test("source control refuses embedded credential publication",async()=>{var path=Path.Combine(root,"Config.txt");File.WriteAllText(path,"password = synthetic-value");await Reject(async()=>{await service.Preview(Request("stage",path));});});
await Test("git preview binds changed configuration",async()=>{var plan=await service.Preview(Request("stage",file));await Command(git,root,"config","infinity.qa","changed");await Reject(async()=>{await service.Apply(plan,true,true);});});
await Test("git preview contains new file text",async()=>{var path=Path.Combine(root,"New.txt");File.WriteAllText(path,"Review this new content");Assert((await service.Preview(Request("stage",path))).Review.Contains("Review this new content"));});
await Test("git review binds independently staged content",async()=>{File.WriteAllText(file,"staged version one\n");await Command(git,root,"add","Example.txt");File.WriteAllText(file,"working version\n");var plan=await service.Preview(Request("unstage",file));File.WriteAllText(file,"staged version two\n");await Command(git,root,"add","Example.txt");File.WriteAllText(file,"working version\n");await Reject(async()=>{await service.Apply(plan,true,true);});});
await Test("git fetch and push work with isolated local remote",async()=>{var remote=Path.Combine(Path.GetDirectoryName(root)!,"bare-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(remote);await Command(git,remote,"init","--bare");await Command(git,root,"remote","add","origin",remote);Assert((await service.Apply(await service.Preview(Request("push")),true,true)).ExitCode==0);Assert((await service.Apply(await service.Preview(Request("fetch")),true,true)).ExitCode==0);Assert((await Command(git,remote,"log","-1","--format=%s","main")).Contains("Reviewed QA change"));});
await Test("git command arguments preserve metacharacters as literal filename",async()=>{var name="literal & quoted.txt";File.WriteAllText(Path.Combine(root,name),"literal\n");var result=await service.Apply(await service.Preview(Request("stage",name)),true,true);Assert(result.ExitCode==0&&(await Command(git,root,"diff","--cached","--name-only")).Contains(name));});
await Test("tfvc builds explicit noninteractive commands",()=>{var req=new SourceRequest(SourceProvider.TFVC,root,"commit",file,"Reviewed comment");var argv=service.Arguments(req);Assert(argv[0]=="vc"&&argv[1]=="checkin"&&argv.Contains("/noprompt")&&argv.Contains("./Example.txt")&&argv.Contains("/comment:Reviewed comment"));foreach(var op in new[]{"status","diff","history","stage","checkout"})Assert(service.Arguments(req with{Operation=op}).Contains("/noprompt"));return Task.CompletedTask;});
await Test("tfvc failed base diff refuses checkin preview",async()=>{var fixture=new SourceControl([root],_=>Path.Combine(AppContext.BaseDirectory,"LocalAI.SourceTests.exe"));await Reject(async()=>{await fixture.Preview(new(SourceProvider.TFVC,root,"commit",file,"Synthetic checkin"));});});
await Test("tfvc new add reviews exact content without base diff",async()=>{var fixture=new SourceControl([root],_=>Path.Combine(AppContext.BaseDirectory,"LocalAI.SourceTests.exe"));var plan=await fixture.Preview(new(SourceProvider.TFVC,root,"stage",file));Assert(plan.Review.Contains("working version")&&(await fixture.Apply(plan,true,true)).ExitCode==0);});
await Test("teams encodes recipients and reviewed draft",()=>{var uri=TeamsIntegration.Draft("qa@example.invalid,second@example.invalid","Review: A&B? #世界\nnext line");Assert(uri.Host=="teams.microsoft.com"&&uri.AbsoluteUri.Contains("%26")&&Uri.UnescapeDataString(uri.Query).Contains("Review: A&B? #世界\nnext line"));return Task.CompletedTask;});
await Test("teams refuses missing recipients and excessive draft",async()=>{await Reject(()=>{TeamsIntegration.Draft("not-an-email","hello");return Task.CompletedTask;});await Reject(()=>{TeamsIntegration.Draft("qa@example.invalid",new string('x',1501));return Task.CompletedTask;});});
if(args.Length>2&&args[1]=="--svn")
{
    var svn=Path.GetFullPath(args[2]);var svnadmin=Path.Combine(Path.GetDirectoryName(svn)!,"svnadmin.exe");var repo=Path.Combine(Path.GetDirectoryName(root)!,"svn-repo-"+Guid.NewGuid().ToString("N"));await Command(svnadmin,root,"create",repo);var wc=Path.Combine(Path.GetDirectoryName(root)!,"svn-working-"+Guid.NewGuid().ToString("N"));await Command(svn,root,"checkout",new Uri(repo+Path.DirectorySeparatorChar).AbsoluteUri,wc,"--non-interactive");
    var client=new SourceControl([wc],_=>svn);var path=Path.Combine(wc,"Example.txt");File.WriteAllText(path,"svn original\n");SourceRequest Svn(string op)=>new(SourceProvider.Subversion,wc,op,path,"Reviewed SVN fixture");
    await Test("svn adds and commits real local working copy",async()=>{Assert((await client.Apply(await client.Preview(Svn("stage")),true,true)).ExitCode==0);Assert((await client.Apply(await client.Preview(Svn("commit")),true,true)).ExitCode==0);});
    await Test("svn reads status diff and server history",async()=>{File.WriteAllText(path,"svn reviewed\n");Assert((await client.Read(Svn("status"))).Output.Contains("Example.txt")&&(await client.Read(Svn("diff"))).Output.Contains("+svn reviewed")&&(await client.Read(Svn("history"))).Output.Contains("Reviewed SVN fixture"));});
    await Test("svn stale preview refuses commit",async()=>{var plan=await client.Preview(Svn("commit"));File.WriteAllText(path,"svn outside change\n");await Reject(async()=>{await client.Apply(plan,true,true);});});
    await Test("svn commits only selected change",async()=>{File.WriteAllText(Path.Combine(wc,"Other.txt"),"unrelated\n");await Command(svn,wc,"add","Other.txt");Assert((await client.Apply(await client.Preview(Svn("commit")),true,true)).ExitCode==0&&(await client.Read(Svn("status"))).Output.Contains("Other.txt"));});
}
File.WriteAllText(output,JsonSerializer.Serialize(rows,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(JsonSerializer.Serialize(new{count=rows.Count,passed=rows.Values.All(v=>v is true),root}));Environment.ExitCode=rows.Values.All(v=>v is true)?0:1;
